              <header className="px-2.5 pt-1 pb-[18px] max-[700px]:px-1 max-[700px]:pt-0 max-[700px]:pb-3">
                <h2
                  id="settings-modal-title"
                  className="m-0 font-sans text-[15px]/5 font-semibold text-ink"
                >
                  Settings
                </h2>
              </header>
              <Tabs.List className="flex flex-col gap-0.5" activateOnFocus>
                {/* Stays selected under Licenses, so a press has to lead back itself. */}
                <RailTab
                  value="general"
                  icon={Settings01Icon}
                  label="General"
                  onClick={() => onTabChange("general")}
                />
                <RailTab value="appearance" icon={PaintBoardIcon} label="Appearance" />
                <RailTab value="data" icon={Database02Icon} label="Library" />
                <RailTab
                  value="archive"
                  icon={Archive01Icon}
                  label="Archive"
                  count={archive.isLoaded ? archive.items.length : undefined}
                />
                <RailTab value="extension" icon={Link01Icon} label="Browser extension" />
              </Tabs.List>
              <div className="mt-auto flex flex-col gap-1 px-2.5">
                {appVersion && (
                  <p className="m-0 font-mono text-[11px]/[14px] font-normal text-[#5e5850]">
                    inkling {appVersion}
                  </p>
                )}
              </div>
            </aside>

            {tab === "licenses" ? (
              <OpenSourceLicenses onBack={() => onTabChange("general")} onClose={onClose} />
            ) : (
              <SettingsPanel tab="general" titleId="general-panel-title">
                <SettingsHeader
                  titleId="general-panel-title"
                  title="General"
                  note="How inkling behaves across the app."
                  onClose={onClose}
                />
                <div className={SETTINGS_SCROLL}>
                  <SettingsRow
                    icon={PlayIcon}
                    title="Welcome tour"
                    description="Replay the screens from your first launch: saving things, finding them again, and keeping your library on this comput
                    action={
                      <button type="button" className={pillButton()} onClick={onShowWelcome}>
                        Show the welcome again
                      </button>
                    }
                  />
                  <SettingsRow
                    icon={LicenseThirdPartyIcon}
                    title="Open source licenses"
                    description="The projects inkling is built on, and the terms they come with."
                    action={
                      <button
                        type="button"
                        className={pillButton()}
                        onClick={() => onTabChange("licenses")}
                      >
                        View licenses
                      </button>
                    }
                  />
                </div>
              </SettingsPanel>
            )}

}) {
  const [open, setOpen] = useState(false);
  const containerRef = useRef<HTMLSpanElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  return (
    <Menu.Root open={open} onOpenChange={setOpen} modal={false}>
      <Menu.Trigger
        ref={triggerRef}
        className={BAR_BUTTON}
        aria-label="Move to Space"
        data-tooltip="Move to Space"
      >
        <BarGlyph>
          <path d="M3 7a2 2 0 0 1 2-2h4l2 2h8a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z" />
        </BarGlyph>
      </Menu.Trigger>
      <span ref={containerRef} className="contents" />
      {/* Kept inside the item view so its stacking and focus handling still hold. */}
      <Menu.Portal container={containerRef}>
        {/* The offset lines the popup's bottom up 6px above the bar's top border. */}
        <Menu.Positioner side="top" align="start" sideOffset={12.5} className="z-2">
          <Menu.Popup
            className="max-h-[280px] w-[232px] overflow-y-auto rounded-[12px] border border-border bg-surface p-1.5 shadow-[0_16px_40px_rgba(0,0,0,0.5
            onFocus={focusFirstMenuItem}
            onKeyDown={(event) => {
              // Escape here closes only the menu, never the item view.
              if (event.key !== "Escape" && event.key !== "Tab") return;
              event.preventDefault();
              event.stopPropagation();
              setOpen(false);
              triggerRef.current?.focus();
            }}
          >
            <Menu.Group>
              <Menu.GroupLabel className="px-2 py-1.5 font-body text-[11px]/[14px] font-medium tracking-[0.02em] text-muted">
                Keep in a Space
              </Menu.GroupLabel>
              {spaces.map((space) => (
                <Menu.CheckboxItem
                  key={space.id}
                  checked={space.member}
                  onCheckedChange={() => void onToggleSpace?.(item, space.id)}
                  data-tooltip={space.member ? `Remove from ${space.name}` : `Add to ${space.name}`}
                  className="group flex h-8 w-full min-w-0 cursor-pointer items-center gap-2.5 rounded-[8px] px-2 text-left font-body text-[13px] lead
                >
                  <SpaceMark small color={space.color} className="flex-none" />
                  <span className="min-w-0 flex-auto truncate">{space.name}</span>
                  <svg
                    className="flex-none text-accent opacity-0 group-data-checked:opacity-100"
                    width="14"
                    height="14"
                    viewBox="0 0 24 24"
                    aria-hidden="true"
                    fill="none"
                    stroke="currentColor"
                    strokeWidth="2.2"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  >
                    <path d="M5 12.5l4.5 4.5L19 7.5" />
                  </svg>
